// Generates json_golden.txt, the differential test data for the JSON form of
// the protocol messages (src/proto/json.rs), with the Java protobuf runtime,
// Gson and the reference helper classes of Apache Wave.
//
// What is and is not the original code: the per-message JSON classes of the
// original (XxxProtoImpl) are generated by the pst tool from StringTemplate
// templates and wrap protoc-generated classes; neither protoc nor the
// StringTemplate library is available here, so those classes cannot be built.
// Instead toGson/fromGson below are a descriptor-driven transcription of the
// templates org/waveprotocol/pst/templates/proto/{toGsonField,fromGsonField}.st
// (with pst's default useInt52 = true and its Field.isLong/isInt52/isBlob
// rules), run over DynamicMessages built from the reference .proto files.
// Everything the templates call is the real thing: Gson (JsonObject,
// JsonPrimitive, JsonElement.toString), GsonUtil, JsonLongHelper, Codec and
// Int52 from the reference tree, and the envelope is a verbatim copy of
// WebSocketChannel.MessageWrapper.serialize.
//
// Input: a file of tab-separated lines "M <message name> <hex protobuf bytes>
// [...]" (the M lines of an existing json_golden.txt will do; extra fields are
// ignored). To add cases, append "M name hex" lines; the ignored Rust test
// `proto::json::tests::print_golden_input` prints the set the tests cover.
//
// Output, tab-separated, escaped as line() does:
//   M <name> <hex> <json>            a message and its JSON form
//   E <name> <seq> <hex> <json>      the same message in an RPC envelope
// Every JSON form is also parsed back with the transcription of
// fromGsonField.st and must give the same bytes.
//
// To regenerate (from the workspace root, with a JDK and the protobuf-java,
// Guava and Gson jars):
//
//   W=reference/apache-wave/wave/src; T=$(mktemp -d)
//   javac -nowarn -cp $PROTOBUF_JAR:$GUAVA_JAR:$GSON_JAR -d $T/out \
//       -sourcepath $W/main/java crates/resonator-model/testdata/JsonGoldenGenerator.java
//   java -cp $T/out:$PROTOBUF_JAR:$GUAVA_JAR:$GSON_JAR JsonGoldenGenerator \
//       $W/proto/proto INPUT > crates/resonator-model/testdata/json_golden.txt

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonPrimitive;
import com.google.protobuf.ByteString;
import com.google.protobuf.DescriptorProtos.DescriptorProto;
import com.google.protobuf.DescriptorProtos.EnumDescriptorProto;
import com.google.protobuf.DescriptorProtos.EnumValueDescriptorProto;
import com.google.protobuf.DescriptorProtos.FieldDescriptorProto;
import com.google.protobuf.DescriptorProtos.FileDescriptorProto;
import com.google.protobuf.Descriptors.Descriptor;
import com.google.protobuf.Descriptors.EnumValueDescriptor;
import com.google.protobuf.Descriptors.FieldDescriptor;
import com.google.protobuf.Descriptors.FileDescriptor;
import com.google.protobuf.DynamicMessage;
import com.google.protobuf.Message;

import org.waveprotocol.wave.communication.Codec;
import org.waveprotocol.wave.communication.gson.GsonUtil;
import org.waveprotocol.wave.communication.proto.Int52;

import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class JsonGoldenGenerator {
  static PrintStream out;

  // Fields are tab-separated; characters outside printable ASCII and the
  // backslash are written as backslash-u escapes (four hex digits) of their
  // UTF-16 code units.
  static void line(Object... fields) {
    StringBuilder b = new StringBuilder();
    for (int i = 0; i < fields.length; i++) {
      if (i > 0) b.append('\t');
      String s = String.valueOf(fields[i]);
      for (int j = 0; j < s.length(); j++) {
        char c = s.charAt(j);
        if (c >= 0x20 && c < 0x7F && c != '\\') {
          b.append(c);
        } else {
          b.append(String.format("\\u%04X", (int) c));
        }
      }
    }
    out.println(b);
  }

  static String hex(byte[] bytes) {
    StringBuilder b = new StringBuilder();
    for (byte x : bytes) b.append(String.format("%02x", x & 0xff));
    return b.toString();
  }

  static byte[] unhex(String s) {
    byte[] r = new byte[s.length() / 2];
    for (int i = 0; i < r.length; i++) {
      r[i] = (byte) Integer.parseInt(s.substring(2 * i, 2 * i + 2), 16);
    }
    return r;
  }

  // ---- Minimal .proto (proto2) parser producing descriptors (as in
  // WaveGoldenGenerator, plus the int52 field option). ----

  static List<String> tokenize(String src) {
    List<String> tokens = new ArrayList<String>();
    int i = 0;
    while (i < src.length()) {
      char c = src.charAt(i);
      if (Character.isWhitespace(c)) {
        i++;
      } else if (src.startsWith("//", i)) {
        while (i < src.length() && src.charAt(i) != '\n') i++;
      } else if (src.startsWith("/*", i)) {
        i = src.indexOf("*/", i) + 2;
      } else if (c == '"') {
        int j = src.indexOf('"', i + 1);
        tokens.add(src.substring(i, j + 1));
        i = j + 1;
      } else if (Character.isLetterOrDigit(c) || c == '_' || c == '.') {
        int j = i;
        while (j < src.length() && (Character.isLetterOrDigit(src.charAt(j))
            || src.charAt(j) == '_' || src.charAt(j) == '.')) j++;
        tokens.add(src.substring(i, j));
        i = j;
      } else {
        tokens.add(String.valueOf(c));
        i++;
      }
    }
    return tokens;
  }

  static final Map<String, FieldDescriptorProto.Type> SCALARS =
      new HashMap<String, FieldDescriptorProto.Type>();
  static {
    SCALARS.put("string", FieldDescriptorProto.Type.TYPE_STRING);
    SCALARS.put("bytes", FieldDescriptorProto.Type.TYPE_BYTES);
    SCALARS.put("bool", FieldDescriptorProto.Type.TYPE_BOOL);
    SCALARS.put("int32", FieldDescriptorProto.Type.TYPE_INT32);
    SCALARS.put("int64", FieldDescriptorProto.Type.TYPE_INT64);
  }

  /** Full names ("Message.field") of the fields declared with [(int52) = true]. */
  static final Set<String> INT52 = new HashSet<String>();

  static class Parser {
    final List<String> t;
    int p = 0;
    Parser(List<String> t) { this.t = t; }
    String next() { return t.get(p++); }
    void expect(String s) {
      String n = next();
      if (!n.equals(s)) throw new IllegalStateException("expected " + s + " got " + n);
    }
    List<String> skipStatement() {
      List<String> skipped = new ArrayList<String>();
      while (true) {
        String n = next();
        if (n.equals(";")) return skipped;
        skipped.add(n);
      }
    }
    void skipBlock() {
      expect("{");
      int depth = 1;
      while (depth > 0) {
        String n = next();
        if (n.equals("{")) depth++;
        if (n.equals("}")) depth--;
      }
    }

    FileDescriptorProto file(String name, String... deps) {
      FileDescriptorProto.Builder f = FileDescriptorProto.newBuilder().setName(name);
      for (String d : deps) f.addDependency(d);
      while (p < t.size()) {
        String n = next();
        if (n.equals("package")) {
          f.setPackage(next());
          expect(";");
        } else if (n.equals("message")) {
          f.addMessageType(message(""));
        } else if (n.equals("enum")) {
          f.addEnumType(enumType());
        } else if (n.equals("service") || n.equals("extend")) {
          next();
          skipBlock();
        } else if (n.equals("syntax") || n.equals("import") || n.equals("option")) {
          skipStatement();
        } else if (!n.equals(";")) {
          throw new IllegalStateException("unexpected " + n);
        }
      }
      return f.build();
    }

    DescriptorProto message(String scope) {
      String name = next();
      DescriptorProto.Builder m = DescriptorProto.newBuilder().setName(name);
      expect("{");
      while (true) {
        String n = next();
        if (n.equals("}")) break;
        if (n.equals("message")) {
          m.addNestedType(message(scope + name + "."));
        } else if (n.equals("enum")) {
          m.addEnumType(enumType());
        } else if (n.equals("option")) {
          skipStatement();
        } else if (n.equals(";")) {
          // empty statement
        } else {
          FieldDescriptorProto.Builder fld = FieldDescriptorProto.newBuilder();
          if (n.equals("required")) fld.setLabel(FieldDescriptorProto.Label.LABEL_REQUIRED);
          else if (n.equals("optional")) fld.setLabel(FieldDescriptorProto.Label.LABEL_OPTIONAL);
          else if (n.equals("repeated")) fld.setLabel(FieldDescriptorProto.Label.LABEL_REPEATED);
          else throw new IllegalStateException("unexpected label " + n);
          String type = next();
          if (SCALARS.containsKey(type)) fld.setType(SCALARS.get(type));
          else fld.setTypeName(type);
          fld.setName(next());
          expect("=");
          fld.setNumber(Integer.parseInt(next()));
          // The options: only (int52) = true matters here.
          List<String> options = skipStatement();
          int at = options.indexOf("int52");
          if (at >= 0 && options.subList(at, options.size()).contains("true")) {
            INT52.add(scope + name + "." + fld.getName());
          }
          m.addField(fld);
        }
      }
      return m.build();
    }

    EnumDescriptorProto enumType() {
      EnumDescriptorProto.Builder e = EnumDescriptorProto.newBuilder().setName(next());
      expect("{");
      while (true) {
        String n = next();
        if (n.equals("}")) break;
        expect("=");
        e.addValue(EnumValueDescriptorProto.newBuilder().setName(n)
            .setNumber(Integer.parseInt(next())));
        expect(";");
      }
      return e.build();
    }
  }

  static final Map<String, Descriptor> BY_NAME = new HashMap<String, Descriptor>();

  static void register(Descriptor d) {
    // ProtoSerializer keys by simple class name.
    if (BY_NAME.put(d.getName(), d) != null) {
      throw new IllegalStateException("duplicate message name " + d.getName());
    }
    for (Descriptor nested : d.getNestedTypes()) register(nested);
  }

  static FileDescriptor load(String root, String path, FileDescriptor... deps) throws Exception {
    String src = new String(Files.readAllBytes(Paths.get(root, path)), StandardCharsets.UTF_8);
    String[] depNames = new String[deps.length];
    for (int i = 0; i < deps.length; i++) depNames[i] = deps[i].getName();
    FileDescriptor fd =
        FileDescriptor.buildFrom(new Parser(tokenize(src)).file(path, depNames), deps);
    for (Descriptor d : fd.getMessageTypes()) register(d);
    return fd;
  }

  /** Field.isInt52() of pst, with the default useInt52 = true. */
  static boolean isInt52(FieldDescriptor f) {
    String scope = f.getContainingType().getFullName();
    String pkg = f.getFile().getPackage();
    if (!pkg.isEmpty()) scope = scope.substring(pkg.length() + 1);
    return INT52.contains(scope + "." + f.getName());
  }

  // ---- Transcription of templates/proto/toGsonField.st. ----

  static JsonElement valueToGson(FieldDescriptor f, Object v) {
    switch (f.getJavaType()) {
      case MESSAGE:
        return toGson((Message) v);
      case ENUM:
        return new JsonPrimitive(((EnumValueDescriptor) v).getNumber());
      case BYTE_STRING:
        // The ProtoImpl getter: new Blob(Codec.encode(bytes)); then blob.getData().
        return new JsonPrimitive(Codec.encode(((ByteString) v).toByteArray()));
      case LONG:
        if (isInt52(f)) {
          // The ProtoImpl getter returns double: Int52.int64to52(long).
          return new JsonPrimitive(Int52.int64to52((Long) v));
        }
        return GsonUtil.toJson((Long) v);
      case INT:
        return new JsonPrimitive((Integer) v);
      case BOOLEAN:
        return new JsonPrimitive((Boolean) v);
      case STRING:
        return new JsonPrimitive((String) v);
      default:
        throw new IllegalStateException("unsupported type " + f.getJavaType());
    }
  }

  static JsonElement toGson(Message m) {
    JsonObject json = new JsonObject();
    for (FieldDescriptor f : m.getDescriptorForType().getFields()) {
      String key = String.valueOf(f.getNumber());
      if (f.isRepeated()) {
        JsonArray array = new JsonArray();
        for (int i = 0; i < m.getRepeatedFieldCount(f); i++) {
          array.add(valueToGson(f, m.getRepeatedField(f, i)));
        }
        json.add(key, array);
      } else if (f.isOptional()) {
        if (m.hasField(f)) {
          json.add(key, valueToGson(f, m.getField(f)));
        }
      } else {
        json.add(key, valueToGson(f, m.getField(f)));
      }
    }
    return json;
  }

  // ---- Transcription of templates/proto/fromGsonField.st. ----

  static Object valueFromGson(FieldDescriptor f, JsonElement e) {
    switch (f.getJavaType()) {
      case MESSAGE:
        // GsonUtil.extractJsonObject without RawStringData.
        return fromGson(f.getMessageType(), e.getAsJsonObject());
      case ENUM:
        return f.getEnumType().findValueByNumber(e.getAsInt());
      case BYTE_STRING:
        return ByteString.copyFrom(Codec.decode(e.getAsString()));
      case LONG:
        if (isInt52(f)) {
          return Int52.int52to64(e.getAsDouble());
        }
        return GsonUtil.fromJson(e);
      case INT:
        return e.getAsInt();
      case BOOLEAN:
        return e.getAsBoolean();
      case STRING:
        return e.getAsString();
      default:
        throw new IllegalStateException("unsupported type " + f.getJavaType());
    }
  }

  static Message fromGson(Descriptor d, JsonObject json) {
    DynamicMessage.Builder b = DynamicMessage.newBuilder(d);
    for (FieldDescriptor f : d.getFields()) {
      String key = String.valueOf(f.getNumber());
      if (!json.has(key)) continue;
      JsonElement elem = json.get(key);
      if (f.isOptional() && elem.isJsonNull()) continue;
      if (f.isRepeated()) {
        JsonArray array = elem.getAsJsonArray();
        for (int i = 0; i < array.size(); i++) {
          b.addRepeatedField(f, valueFromGson(f, array.get(i)));
        }
      } else {
        b.setField(f, valueFromGson(f, elem));
      }
    }
    return b.build();
  }

  // ---- Verbatim from WebSocketChannel.MessageWrapper. ----

  public static String serialize(String type, int seqno, JsonElement message) {
    JsonObject o = new JsonObject();
    o.add("messageType", new JsonPrimitive(type));
    o.add("sequenceNumber", new JsonPrimitive(seqno));
    o.add("message", message);
    return o.toString();
  }

  public static void main(String[] args) throws Exception {
    out = new PrintStream(System.out, false, "UTF-8");
    String root = args[0];
    FileDescriptor federation =
        load(root, "org/waveprotocol/wave/federation/federation.protodevel");
    load(root, "org/waveprotocol/box/server/rpc/rpc.proto");
    load(root, "org/waveprotocol/box/common/comms/waveclient-rpc.proto", federation);
    load(root, "org/waveprotocol/box/profile/profiles.proto");
    load(root, "org/waveprotocol/box/search/search.proto");
    load(root, "org/waveprotocol/box/attachment/attachment.proto");
    int seqno = 0;
    for (String inputLine : Files.readAllLines(Paths.get(args[1]), StandardCharsets.UTF_8)) {
      String[] fields = inputLine.split("\t", -1);
      if (fields.length < 3 || !fields[0].equals("M")) continue;
      String name = fields[1];
      Descriptor d = BY_NAME.get(name);
      if (d == null) throw new IllegalStateException("unknown message " + name);
      byte[] bytes = unhex(fields[2]);
      Message m = DynamicMessage.parseFrom(d, bytes);
      if (!m.isInitialized()) throw new IllegalStateException("uninitialized " + name);
      JsonElement json = toGson(m);
      String text = json.toString();
      // Round trip through text, as the server does for received messages.
      Message back = fromGson(d, new JsonParser().parse(text).getAsJsonObject());
      if (!back.toByteString().equals(m.toByteString())) {
        throw new IllegalStateException("round trip failed for " + name + ": " + text);
      }
      line("M", name, fields[2], text);
      line("E", name, seqno, fields[2], serialize(name, seqno, json));
      seqno = seqno * 7 + 3;
      if (seqno > 100000000) seqno = -5;
    }
    out.flush();
  }
}
